  3405	node_min_byte_len(Node* node, ScanEnv* env)
  3406	{
  3407	  OnigLen len;
  3408	  OnigLen tmin;
  3409	
  3410	  len = 0;
  3411	  switch (NODE_TYPE(node)) {
  3412	  case NODE_BACKREF:
  3413	    if (! NODE_IS_CHECKER(node)) {
  3414	      int i;
  3415	      int* backs;
  3416	      MemEnv* mem_env = SCANENV_MEMENV(env);
  3417	      BackRefNode* br = BACKREF_(node);
  3418	      if (NODE_IS_RECURSION(node)) break;
  3419	
  3420	      backs = BACKREFS_P(br);
  3421	      len = node_min_byte_len(mem_env[backs[0]].mem_node, env);
  3422	      for (i = 1; i < br->back_num; i++) {
  3423	        tmin = node_min_byte_len(mem_env[backs[i]].mem_node, env);
  3424	        if (len > tmin) len = tmin;
  3425	      }
  3426	    }
  3427	    break;
  3428	
  3429	#ifdef USE_CALL
  3430	  case NODE_CALL:
  3431	    {
  3432	      Node* t = NODE_BODY(node);
  3433	      if (NODE_IS_RECURSION(node)) {
  3434	        if (NODE_IS_FIXED_MIN(t))
  3435	          len = BAG_(t)->min_len;
  3436	      }
  3437	      else
  3438	        len = node_min_byte_len(t, env);
  3439	    }
  3440	    break;
  3441	#endif
  3442	
  3443	  case NODE_LIST:
  3444	    do {
  3445	      tmin = node_min_byte_len(NODE_CAR(node), env);
  3446	      len = distance_add(len, tmin);
  3447	    } while (IS_NOT_NULL(node = NODE_CDR(node)));
  3448	    break;
  3449	
  3450	  case NODE_ALT:
  3451	    {
  3452	      Node *x, *y;
  3453	      y = node;
  3454	      do {
  3455	        x = NODE_CAR(y);
  3456	        tmin = node_min_byte_len(x, env);
  3457	        if (y == node) len = tmin;
  3458	        else if (len > tmin) len = tmin;
  3459	      } while (IS_NOT_NULL(y = NODE_CDR(y)));
  3460	    }
  3461	    break;
  3462	
  3463	  case NODE_STRING:
  3464	    {
  3465	      StrNode* sn = STR_(node);
  3466	      len = (int )(sn->end - sn->s);
  3467	    }
  3468	    break;
  3469	
  3470	  case NODE_CTYPE:
  3471	  case NODE_CCLASS:
  3472	    len = ONIGENC_MBC_MINLEN(env->enc);
  3473	    break;
  3474	
  3475	  case NODE_QUANT:
  3476	    {
  3477	      QuantNode* qn = QUANT_(node);
  3478	
  3479	      if (qn->lower > 0) {
  3480	        len = node_min_byte_len(NODE_BODY(node), env);
  3481	        len = distance_multiply(len, qn->lower);
  3482	      }
  3483	    }
  3484	    break;
  3485	
  3486	  case NODE_BAG:
  3487	    {
  3488	      BagNode* en = BAG_(node);
  3489	      switch (en->type) {
  3490	      case BAG_MEMORY:
  3491	        if (NODE_IS_FIXED_MIN(node))
  3492	          len = en->min_len;
  3493	        else {
  3494	          if (NODE_IS_MARK1(node))
  3495	            len = 0;  /* recursive */
  3496	          else {
  3497	            NODE_STATUS_ADD(node, MARK1);
  3498	            len = node_min_byte_len(NODE_BODY(node), env);
  3499	            NODE_STATUS_REMOVE(node, MARK1);
  3500	
  3501	            en->min_len = len;
  3502	            NODE_STATUS_ADD(node, FIXED_MIN);
  3503	          }
  3504	        }
  3505	        break;
  3506	
  3507	      case BAG_OPTION:
  3508	      case BAG_STOP_BACKTRACK:
  3509	        len = node_min_byte_len(NODE_BODY(node), env);
  3510	        break;
  3511	      case BAG_IF_ELSE:
  3512	        {
  3513	          OnigLen elen;
  3514	
  3515	          len = node_min_byte_len(NODE_BODY(node), env);
  3516	          if (IS_NOT_NULL(en->te.Then))
  3517	            len += node_min_byte_len(en->te.Then, env);
  3518	          if (IS_NOT_NULL(en->te.Else))
  3519	            elen = node_min_byte_len(en->te.Else, env);
  3520	          else elen = 0;
  3521	
  3522	          if (elen < len) len = elen;
  3523	        }
  3524	        break;
  3525	      }
  3526	    }
  3527	    break;
  3528	
  3529	  case NODE_GIMMICK:
  3530	    {
  3531	      GimmickNode* g = GIMMICK_(node);
  3532	      if (g->type == GIMMICK_FAIL) {
